+import { isString } from './shared.utils';
+
+/**
+ * Sanitizes the Content-Type header value to prevent code injection attacks.
+ * Only allows valid MIME type characters and structure, rejecting any potentially malicious input.
+ *
+ * @param contentType The raw Content-Type header value
+ * @returns The sanitized Content-Type value, or undefined if the input is invalid or malicious
+ */
+export function sanitizeContentType(contentType: unknown): string | undefined {
+  if (!isString(contentType)) {
+    return undefined;
+  }
+
+  // Regex to match safe MIME type patterns, rejecting characters commonly used for code injection (quotes, parentheses, angle brackets, etc.)
+  const validMimeTypeRegex = /^[a-zA-Z0-9\/\-\+\.\;\,\=\s]+$/;
+  const trimmedContentType = contentType.trim();
+
+  if (!validMimeTypeRegex.test(trimmedContentType)) {
+    return undefined;
+  }
+
+  return trimmedContentType;
+}
